package com.jbrempresa.backend.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="reserva_recursos") public class ReservaRecurso{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="rer_id")private Long rerId;@Column(name="emp_id",nullable=false)private Long empId;@Column(name="res_id",nullable=false)private Long resId;@Column(name="rag_id",nullable=false)private Long ragId;@Column(name="rer_ini_ocu",nullable=false)private LocalDateTime rerIniOcu;@Column(name="rer_fin_ocu",nullable=false)private LocalDateTime rerFinOcu;@Column(name="rer_usu_mov",nullable=false,length=100)private String rerUsuMov;@Column(name="rer_fec_mov",nullable=false)private LocalDateTime rerFecMov;@Column(name="rer_act",nullable=false)private Boolean rerAct;
 public Long getRerId(){return rerId;}public void setRerId(Long v){rerId=v;}public Long getEmpId(){return empId;}public void setEmpId(Long v){empId=v;}public Long getResId(){return resId;}public void setResId(Long v){resId=v;}public Long getRagId(){return ragId;}public void setRagId(Long v){ragId=v;}public LocalDateTime getRerIniOcu(){return rerIniOcu;}public void setRerIniOcu(LocalDateTime v){rerIniOcu=v;}public LocalDateTime getRerFinOcu(){return rerFinOcu;}public void setRerFinOcu(LocalDateTime v){rerFinOcu=v;}public String getRerUsuMov(){return rerUsuMov;}public void setRerUsuMov(String v){rerUsuMov=v;}public LocalDateTime getRerFecMov(){return rerFecMov;}public void setRerFecMov(LocalDateTime v){rerFecMov=v;}public Boolean getRerAct(){return rerAct;}public void setRerAct(Boolean v){rerAct=v;}
}
